import { icon, escapeHtml } from './ui.js';
import { renderMarmelada } from './marmelada.js';

export const ADMIN_ROUTES = ['admin', 'admin-group', 'admin-user', 'admin-marmelada'];
const escape = escapeHtml;
const number = value => Number(value || 0).toLocaleString('pt-BR');
const date = value => value ? new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC' }).format(new Date(String(value).length === 10 ? `${value}T12:00:00Z` : value)) : '—';
const money = value => Number(value || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const name = person => person?.name || [person?.firstName, person?.lastName].filter(Boolean).join(' ') || person?.email || 'Pessoa convidada';
const status = value => ({ accepted: ['Participando', 'green'], opened: ['Abertura estimada', 'blue'], delivered: ['Entregue', 'green'], sent: ['Enviado', 'green'], failed: ['Falha no envio', 'red'] }[value] || ['Convidado', 'neutral']);
const pill = (text, tone = 'neutral') => `<span class="group-status group-status-${tone}">${escape(text)}</span>`;
const memberStatus = value => pill(...status(value));
const groupStatus = group => pill(group.drawn || group.drawnAt ? 'Sorteado' : 'Aguardando sorteio', group.drawn || group.drawnAt ? 'green' : 'neutral');
const link = (route, id, label, className = '') => `<a class="${className}" href="#${route}?id=${encodeURIComponent(id)}" data-route="${route}" data-admin-id="${escape(id)}">${escape(label)}</a>`;
const person = user => `<span class="admin-person"><strong>${escape(name(user))}</strong><span>${escape(user?.email || '')}</span></span>`;
const restricted = () => `<span class="admin-private-label">${icon('lock', 14)} Acesso exclusivo da sua conta</span>`;
const back = (tab = 'groups') => `<a class="group-back" href="#admin?tab=${tab}" data-route="admin?tab=${tab}">${icon('arrow-left', 16)} Administração</a>`;

function pagination(data, tab, search) {
  const page = Math.max(1, Number(data?.page) || 1), totalPages = Math.max(1, Number(data?.totalPages) || 1);
  const target = next => `admin?${new URLSearchParams({ tab, page: String(next), ...(search ? { search } : {}) })}`;
  return `<div class="admin-pagination"><span>${number(data?.total)} registros · página ${page} de ${totalPages}</span><div><button class="btn btn-secondary" data-route="${escape(target(page - 1))}" ${page <= 1 ? 'disabled' : ''}>${icon('arrow-left', 15)} Anterior</button><button class="btn btn-secondary" data-route="${escape(target(page + 1))}" ${page >= totalPages ? 'disabled' : ''}>Próxima ${icon('arrow-right', 15)}</button></div></div>`;
}
function groupTable(groups, { compact = false, empty = 'Nenhum amigo secreto encontrado.' } = {}) {
  return `<div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>AMIGO SECRETO</th>${compact ? '' : '<th>QUEM CRIOU</th>'}<th>PARTICIPANTES</th><th>SITUAÇÃO</th><th><span class="group-sr-only">Detalhes</span></th></tr></thead><tbody>${groups.map(group => `<tr><td data-label="AMIGO SECRETO"><strong>${link('admin-group', group.id, group.name)}</strong><small>${date(group.date || group.eventDate)}${group.membershipStatus ? ` · ${escape(status(group.membershipStatus)[0])}` : ''}</small></td>${compact ? '' : `<td data-label="QUEM CRIOU">${person(group.organizer || { name: group.organizerName, email: group.organizerEmail })}</td>`}<td data-label="PARTICIPANTES"><strong>${number(group.acceptedCount)}</strong><small>de ${number(group.participantCount)} confirmados</small></td><td data-label="SITUAÇÃO">${groupStatus(group)}</td><td data-label="DETALHES">${link('admin-group', group.id, 'Ver detalhes', 'admin-detail-link')}</td></tr>`).join('') || `<tr><td data-label="" colspan="${compact ? 4 : 5}" class="admin-empty">${escape(empty)}</td></tr>`}</tbody></table></div>`;
}
function usersTable(users) {
  return `<div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>PESSOA</th><th>CADASTRO</th><th>GRUPOS CRIADOS</th><th>PARTICIPAÇÕES</th><th><span class="group-sr-only">Detalhes</span></th></tr></thead><tbody>${users.map(user => `<tr><td data-label="PESSOA">${person(user)}</td><td data-label="CADASTRO">${date(user.createdAt)}</td><td data-label="GRUPOS CRIADOS">${number(user.createdCount)}</td><td data-label="PARTICIPAÇÕES">${number(user.participatingCount)}</td><td data-label="DETALHES">${link('admin-user', user.id, 'Ver pessoa', 'admin-detail-link')}</td></tr>`).join('') || '<tr><td data-label="" colspan="5" class="admin-empty">Nenhuma pessoa encontrada.</td></tr>'}</tbody></table></div>`;
}
function overview(state) {
  const counts = state.adminOverview?.summary || {}, data = state.adminData || {}, tab = state.adminTab || 'groups';
  const cards = [['gift', 'Amigos secretos', counts.groups], ['sparkles', 'Sorteios realizados', counts.drawnGroups], ['users', 'Pessoas cadastradas', counts.users], ['check-circle', 'Participações confirmadas', counts.participants]];
  return `<section class="admin-page"><div class="admin-title-row"><div><span class="eyebrow">UM OLHAR SOBRE TODOS OS ENCONTROS</span><h1>Administração<span>.</span></h1><p>Grupos, pessoas e resultados em um só lugar.</p></div>${restricted()}</div><div class="admin-stats">${cards.map(([glyph, label, value]) => `<article class="admin-stat panel"><span>${icon(glyph, 20)}</span><strong>${number(value)}</strong><p>${label}</p></article>`).join('')}</div><section class="panel admin-list-panel"><div class="admin-list-header"><div class="admin-tabs" aria-label="Listagens administrativas"><button class="${tab === 'groups' ? 'active' : ''}" data-route="admin?tab=groups" aria-pressed="${tab === 'groups'}">${icon('gift', 17)} Amigos secretos</button><button class="${tab === 'users' ? 'active' : ''}" data-route="admin?tab=users" aria-pressed="${tab === 'users'}">${icon('users', 17)} Pessoas</button></div><button class="btn btn-secondary admin-refresh" data-action="refresh-admin">${icon('refresh', 15)} Atualizar</button></div><form class="admin-search" data-form="admin-search"><label for="admin-search-input">${tab === 'groups' ? 'Buscar por grupo ou organizador' : 'Buscar por nome ou e-mail'}</label><div><span>${icon('search', 18)}</span><input id="admin-search-input" type="search" name="search" value="${escape(state.adminSearch || '')}" placeholder="${tab === 'groups' ? 'Nome do grupo, pessoa ou e-mail' : 'Nome ou e-mail da pessoa'}" maxlength="100" autocomplete="off"><button type="submit" class="btn btn-primary">Buscar</button>${state.adminSearch ? `<button type="button" class="btn btn-secondary" data-route="admin?tab=${tab}">Limpar</button>` : ''}</div></form>${tab === 'groups' ? groupTable(data.groups || []) : usersTable(data.users || [])}${pagination(data.pagination, tab, state.adminSearch)}</section><p class="admin-private-note">${icon('shield', 16)} Esta área e seus dados estão disponíveis somente para sua conta administrativa.</p></section>`;
}
function groupDetail(state) {
  const data = state.adminData || {}, group = data.group || {}, members = data.participants || [], results = data.results || [];
  return `<section class="admin-page">${back()}<div class="admin-title-row"><div><span class="eyebrow">DETALHES DO AMIGO SECRETO</span><h1>${escape(group.name)}</h1><p>Criado em ${date(group.createdAt)}</p></div>${restricted()}</div><div class="admin-group-summary panel"><div><span>QUEM CRIOU</span>${person(group.organizer || { name: group.organizerName, email: group.organizerEmail })}${(group.organizer?.id || group.organizerId) ? link('admin-user', group.organizer?.id || group.organizerId, 'Ver cadastro', 'admin-detail-link') : ''}</div><div><span>DATA DA TROCA</span><strong>${date(group.date || group.eventDate)}</strong></div><div><span>VALOR DO PRESENTE</span><strong>${money(group.budget)}</strong></div><div><span>SITUAÇÃO</span>${groupStatus(group)}</div></div><div class="admin-detail-grid"><section class="panel admin-detail-panel"><div class="admin-section-title"><span>${icon('users', 20)}</span><div><h2>Participantes</h2><p>${number(members.length)} pessoas na lista do grupo</p></div></div><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>PESSOA</th><th>CONVITE</th><th><span class="group-sr-only">Cadastro</span></th></tr></thead><tbody>${members.map(member => `<tr><td data-label="PESSOA">${person(member)}</td><td data-label="CONVITE">${memberStatus(member.status)}</td><td data-label="CADASTRO">${member.userId ? link('admin-user', member.userId, 'Ver cadastro', 'admin-detail-link') : '<span class="admin-muted">Sem cadastro</span>'}</td></tr>`).join('') || '<tr><td data-label="" colspan="3" class="admin-empty">Nenhum participante.</td></tr>'}</tbody></table></div></section><section class="panel admin-detail-panel"><div class="admin-section-title"><span>${icon('gift', 20)}</span><div><h2>Resultado do sorteio</h2><p>${group.drawn || group.drawnAt ? `Realizado em ${date(group.drawnAt)}` : 'Aguardando o sorteio do grupo'}</p></div></div>${results.length ? `<div class="admin-result-list">${results.map(result => `<div class="admin-result-pair"><div><small>QUEM PRESENTEIA</small>${person(result.giver)}</div><span aria-label="presenteia">${icon('arrow-right', 19)}</span><div><small>QUEM RECEBE</small>${person(result.receiver)}</div></div>`).join('')}</div>` : `<div class="admin-empty admin-result-empty">${icon('gift', 31)}<p>Os pares aparecerão aqui quando o sorteio for realizado.</p></div>`}</section></div><div class="group-delete-area"><div><strong>Apagar este amigo secreto</strong><p>Consulte o impacto e confirme a exclusão permanente.</p></div><button class="btn btn-danger-outline" data-action="admin-delete-group">${icon('x', 17)} Apagar grupo</button></div></section>`;
}
function userPagination(data, userId, kind, state) {
  if (!data || Number(data.totalPages) <= 1) return '';
  const page = Number(data.page) || 1, totalPages = Number(data.totalPages) || 1;
  const target = next => `admin-user?${new URLSearchParams({ id: userId, createdPage: String(kind === 'created' ? next : state.adminCreatedPage || 1), participatingPage: String(kind === 'participating' ? next : state.adminParticipatingPage || 1) })}`;
  return `<div class="admin-pagination"><span>${number(data.total)} registros · página ${page} de ${totalPages}</span><div><button class="btn btn-secondary" data-route="${escape(target(page - 1))}" ${page <= 1 ? 'disabled' : ''}>${icon('arrow-left', 15)} Anterior</button><button class="btn btn-secondary" data-route="${escape(target(page + 1))}" ${page >= totalPages ? 'disabled' : ''}>Próxima ${icon('arrow-right', 15)}</button></div></div>`;
}
function userDetail(state) {
  const data = state.adminData || {}, user = data.user || {};
  const pages = (pagination, kind) => userPagination(pagination, user.id, kind, state);
  return `<section class="admin-page">${back('users')}<div class="admin-title-row"><div><span class="eyebrow">CADASTRO E ENCONTROS</span><h1>${escape(name(user))}</h1><p>${escape(user.email || '')}</p></div>${restricted()}</div><div class="admin-user-summary panel"><span class="admin-user-symbol">${icon('users', 27)}</span><div><span>CADASTRADO EM</span><strong>${date(user.createdAt)}</strong></div><div><span>GRUPOS CRIADOS</span><strong>${number(data.createdPagination?.total ?? data.groupsCreated?.length)}</strong></div><div><span>PARTICIPAÇÕES</span><strong>${number(data.participatingPagination?.total ?? data.groupsParticipating?.length)}</strong></div></div><section class="panel admin-detail-panel"><div class="admin-section-title"><span>${icon('gift', 20)}</span><div><h2>Amigos secretos que criou</h2><p>Encontros organizados por esta pessoa.</p></div></div>${groupTable(data.groupsCreated || [], { compact: true, empty: 'Esta pessoa ainda não criou um amigo secreto.' })}${pages(data.createdPagination, 'created')}</section><section class="panel admin-detail-panel admin-user-groups"><div class="admin-section-title"><span>${icon('users', 20)}</span><div><h2>Amigos secretos em que participa</h2><p>Participações confirmadas nos grupos da aplicação.</p></div></div>${groupTable(data.groupsParticipating || [], { empty: 'Esta pessoa ainda não possui participações confirmadas.' })}${pages(data.participatingPagination, 'participating')}</section><div class="group-delete-area"><div><strong>Apagar esta conta</strong><p>${user.id === state.user?.id ? 'Sua conta administrativa está protegida contra exclusão.' : 'Consulte o impacto nos grupos e confirme a exclusão permanente.'}</p></div><button class="btn btn-danger-outline" data-action="admin-delete-user" ${user.id === state.user?.id ? 'disabled' : ''}>${icon('x', 17)} Apagar usuário</button></div></section>`;
}
export function renderAdminDeletePreview(kind, preview) {
  const user = kind === 'user', subject = user ? preview.user : preview.group, effects = preview.effects || {};
  const expected = user ? subject.email : subject.name;
  const rows = user ? [
    ['Grupos criados que serão apagados', effects.groupsDeleted],
    ['Participações que serão removidas de outros grupos', effects.membershipsRemoved],
    ['Participações em sorteios que serão anonimizadas', effects.drawnParticipationsAnonymized],
    ['Registros de notificações que serão removidos', effects.notificationsDeleted],
  ] : [
    ['Grupo que será apagado', effects.groupsDeleted], ['Participações e convites que serão apagados', effects.membershipsDeleted],
    ['Pares do sorteio que serão apagados', effects.resultsDeleted], ['Registros de notificações que serão removidos', effects.notificationsDeleted],
  ];
  return `<form class="delete-group-form admin-delete-form"><div class="delete-group-heading"><span class="delete-group-symbol">${icon('alert', 23)}</span><button type="button" class="icon-button" data-action="close-dialog" aria-label="Fechar confirmação">${icon('x', 21)}</button></div><span class="eyebrow">CONFIRA ANTES DE CONFIRMAR</span><h2 id="admin-delete-title">${user ? 'Apagar esta conta?' : 'Apagar este amigo secreto?'}</h2><p><strong>${escape(subject.name || expected)}</strong>${user ? `<br>${escape(subject.email)}` : ''}</p>${preview.canDelete === false ? `<div class="delete-group-warning" role="alert">${icon('lock', 19)}<span>${escape(preview.blockedReason || 'Esta conta administrativa está protegida contra exclusão.')}</span></div>` : `<p>${user ? 'A conta, o perfil, os acessos e todos os grupos criados por esta pessoa serão apagados. Os convites e participações em outros grupos ainda não sorteados também serão removidos.' : 'O grupo, seus convites, participações e todos os resultados do sorteio serão apagados permanentemente. As contas das pessoas continuam na aplicação.'}</p><dl class="admin-delete-effects">${rows.map(([label, count]) => `<div><dt>${label}</dt><dd>${number(count)}</dd></div>`).join('')}</dl>${user && effects.drawnParticipationsAnonymized ? '<p class="admin-delete-anonymized">Nos sorteios já realizados de outros organizadores, a participação ficará anônima para preservar os pares do sorteio.</p>' : ''}<div class="delete-group-warning">${icon('info', 19)}<span>Essa ação não pode ser desfeita. Os e-mails já enviados permanecem nas caixas de entrada.</span></div><label class="field" for="admin-delete-confirmation">Para confirmar, digite ${user ? 'o e-mail' : 'o nome exato do grupo'}:<strong class="delete-group-name">${escape(expected)}</strong><input id="admin-delete-confirmation" name="confirmation" type="text" required autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="${user ? 'E-mail exato da conta' : 'Nome exato do grupo'}"></label>`}<div class="delete-group-actions"><button type="button" class="btn btn-secondary" data-action="close-dialog">${preview.canDelete === false ? 'Entendi' : 'Cancelar'}</button>${preview.canDelete === false ? '' : '<button type="submit" class="btn btn-danger" disabled>Apagar definitivamente</button>'}</div></form>`;
}

export function renderAdmin(route, state) {
  if (!ADMIN_ROUTES.includes(route)) return null;
  if (!state.user?.isAdmin) return '';
  const navigation = `<nav class="admin-section-navigation" aria-label="Administração"><button class="${route !== 'admin-marmelada' ? 'active' : ''}" data-route="admin">${icon('grid', 16)} Visão geral</button><button class="${route === 'admin-marmelada' ? 'active' : ''}" data-route="admin-marmelada">${icon('sparkles', 17)} Marmelada<span>?</span></button></nav>`;
  if (route === 'admin-marmelada') return navigation + renderMarmelada(state);
  if (route === 'admin-group') return navigation + groupDetail(state);
  if (route === 'admin-user') return navigation + userDetail(state);
  return navigation + overview(state);
}
